A.cango = b => { const s = S.sessions.find(x => x.id === b.dataset.id); s.status = 'Cancelled'; save(); closeMod(); toast('Session cancelled'); pushN('batch', 'Session cancelled', s.subj + ' on ' + fmt(s.date) + ' was cancelled.'); render(true); };

/* ---------- ATTENDANCE ---------- */
let atf = 'All';
V.att = { html() { const c = kid(), st = attStats(c), by = c.subs.map(s => { const x = c.att.filter(a => a.sub === s && a.s !== 'n'); return [s, x.length ? Math.round(x.filter(a => a.s !== 'a').length / x.length * 100) : 100, x.length]; });
  const rows = c.att.filter(a => a.s !== 'n').slice().reverse().filter(a => atf === 'All' || ({ p: 'Present', l: 'Late', a: 'Absent' }[a.s]) === atf), nm = { p: 'Present', l: 'Late', a: 'Absent', n: 'No class' };
  return '<h1>Attendance</h1><p class="sb">Last 30 days for ' + esc(c.name) + '.</p><div class="grid g32"><div class="u-d-flex_gap-24_ai-center_fw-wrap-wrap dc"><div class="ring" style="--v:' + st.pct + '"><b>' + st.pct + '%</b></div><div class="u-flex-1_minw-200"><div class="u-gap-10 grid g3"><div class="m"><b>' + st.p + '</b><span>Present</span></div><div class="m"><b>' + st.l + '</b><span>Late</span></div><div class="m"><b>' + st.a + '</b><span>Absent</span></div></div><p class="u-mt-12_c-mu">Current streak: <b>' + streak(c) + ' classes</b> without an absence.</p></div></div><div class="dc"><h3>By subject</h3>' + by.map(b => '<div class="m"><span>' + b[0] + ' · ' + b[1] + '% (' + b[2] + ' classes)</span></div><div class="bar ' + (b[1] >= 90 ? 'ok' : '') + '"><i style="width:' + b[1] + '%"></i></div>').join('') + '</div></div>'
  + '<div class="dc"><h3>Last 30 days</h3><div class="hm" role="img" aria-label="30 day attendance: ' + st.p + ' present, ' + st.a + ' absent, ' + st.l + ' late">' + c.att.map(a => '<button type="button" class="' + (a.s === 'p' ? '' : a.s) + '" title="' + fmt(a.d) + ': ' + nm[a.s] + (a.sub && a.s !== 'n' ? ' (' + a.sub + ')' : '') + '" tabindex="-1" aria-hidden="true"></button>').join('') + '</div><div class="leg"><span><i class="ok"></i>Present</span><span><i class="h"></i>Absent</span><span><i class="l"></i>Late</span><span><i class="u-bg-bd"></i>No class</span></div></div>'
  + '<div class="grid g2"><div class="dc"><h3>Apply for leave</h3><div class="f"><div class="f2">' + field('lv-a', 'From', '<input id="lv-a" type="date" min="' + today() + '">') + field('lv-b', 'To', '<input id="lv-b" type="date" min="' + today() + '">') + '</div>' + field('lv-r', 'Reason', '<select id="lv-r"><option>Illness</option><option>Family function</option><option>School exam</option><option>Travel</option><option>Other</option></select>') + '<button class="btn full" data-act="lvgo" type="button">Submit leave request</button></div>' + (mine(S.leaves).length ? '<ul class="u-mt-12 lst">' + mine(S.leaves).map(l => '<li><span><b>' + fmt(l.a) + (l.b !== l.a ? ' → ' + fmt(l.b) : '') + '</b><small class="sub">' + l.r + '</small></span>' + status(l.status) + '</li>').join('') + '</ul>' : '') + '</div>'
  + '<div class="dc"><div class="hd2"><h3>Attendance log</h3><button class="btn sm2 ghost" data-act="attcsv" type="button">Export CSV</button></div><div class="u-jc-flex-start_mb-8 filters">' + ['All', 'Present', 'Late', 'Absent'].map(f => '<button class="chip ' + (f === atf ? 'on' : '') + '" data-act="atf" data-v="' + f + '" type="button" aria-pressed="' + (f === atf) + '">' + f + '</button>').join('') + '</div><div class="u-maxh-300_oy-auto">' + (rows.length ? '<ul class="lst">' + rows.map(a => '<li><span>' + fmt(a.d) + '<small class="sub">' + a.sub + '</small></span>' + status(nm[a.s]) + '</li>').join('') + '</ul>' : empty('userchk', 'No records for this filter.')) + '</div></div></div>'; } };
A.atf = b => { atf = b.dataset.v; render(true); };
A.attcsv = () => { const c = kid(); download('attendance-' + c.id + '.csv', 'Date,Subject,Status\n' + c.att.filter(a => a.s !== 'n').map(a => a.d + ',' + a.sub + ',' + ({ p: 'Present', l: 'Late', a: 'Absent' }[a.s])).join('\n'), 'text/csv'); toast('CSV downloaded'); };
A.lvgo = () => { const a = $('#lv-a').value, b = $('#lv-b').value || a; let ok = bad('lv-a', a ? '' : 'Choose the first day.'); if (a && b < a) ok = bad('lv-b', 'End date is before the start.') && false; if (!ok) return; const l = { id: uid(), child: S.kid, a, b, r: $('#lv-r').value, status: 'Pending' }; S.leaves.push(l); save(); toast('Leave request sent');
  setTimeout(() => { l.status = 'Approved'; save(); pushN('batch', 'Leave approved', kid().name + ': ' + fmt(l.a) + (l.b !== l.a ? ' to ' + fmt(l.b) : '') + ' is approved.'); if (cur === 'att') render(true); }, 5000); render(true); };

/* ---------- PROGRESS ---------- */
const FB = { Mathematics: 'Participates well. Practise algebra word problems twice a week.', Science: 'Careful in experiments. Label diagrams fully while revising.', English: 'Reads aloud with expression. Needs more essay-writing practice.', 'Computer Science': 'Thinks logically. Practise flowcharts and dry runs.' };
let pt = 'Current';
const reportHtml = term => { const c = kid(), m = c.terms[term], at = attStats(c); return '<!doctype html><meta charset="utf-8"><title>' + esc(c.name) + ' · ' + term + ' report</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:720px;margin:32px auto;padding:0 20px;color:#1d2233}h1{color:#7a1f3d}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:8px;text-align:left}.k{color:#666}</style><h1>BrightPath Tutoring Center</h1><h2>' + esc(c.name) + ' · Grade ' + c.grade + ' · ' + term + ' report</h2><p class="k">Generated ' + new Date().toLocaleDateString('en-IN') + '</p><table><tr><th>Subject</th><th>Marks</th><th>Grade</th><th>Tutor feedback</th></tr>' + c.subs.map(s => '<tr><td>' + s + '</td><td>' + m[s] + '%</td><td>' + letter(m[s]) + '</td><td>' + (FB[s] || '') + '</td></tr>').join('') + '</table><p><b>Overall:</b> ' + avgMarks(c, term).toFixed(1) + '% (' + letter(avgMarks(c, term)) + ') · <b>Attendance:</b> ' + at.pct + '%</p><p class="k">45 Learners Road, Velachery, Chennai · +91 98765 43210</p>'; };
const reportDl = term => { download('report-' + kid().id + '-' + term.toLowerCase().replace(/\W+/g, '-') + '.html', reportHtml(term), 'text/html'); toast(term + ' report downloaded'); addXP(0); };
A.rdl = b => reportDl(b.dataset.t);
A.rpr = b => { const w = open('', '_blank'); if (!w) return toast('Allow pop-ups to print the report.'); w.document.write(reportHtml(b.dataset.t)); w.document.close(); w.focus(); setTimeout(() => w.print(), 300); };
V.prog = { html() { const c = kid(), m = c.terms[pt], T = ['Term 1', 'Mid-term', 'Current'], sorted = c.subs.slice().sort((a, b) => c.marks[b] - c.marks[a]), above = c.subs.filter(s => c.marks[s] > c.avg[s]).length;
  return '<h1>Progress reports</h1><p class="sb">Marks, trends and tutor feedback for ' + esc(c.name) + '.</p><div class="u-jc-flex-start filters">' + T.map(t => '<button class="chip ' + (t === pt ? 'on' : '') + '" data-act="ptm" data-v="' + t + '" type="button" aria-pressed="' + (t === pt) + '">' + t + '</button>').join('') + '</div><div class="grid g32"><div class="dc"><div class="hd2"><h3>' + pt + ' marks' + (pt === 'Current' ? ' vs class average' : '') + '</h3><span class="u-m-0 tag">Overall ' + avgMarks(c, pt).toFixed(0) + '% · ' + letter(avgMarks(c, pt)) + '</span></div><canvas class="u-h-260 cv" id="c-bar" role="img" aria-label="Subject marks chart"></canvas></div><div class="dc"><h3>Insights</h3><ul class="lst"><li><span><b>Strongest</b><small class="sub">' + sorted[0] + ' · ' + c.marks[sorted[0]] + '%</small></span><span class="st ok">▲</span></li><li><span><b>Focus area</b><small class="sub">' + sorted.at(-1) + ' · ' + c.marks[sorted.at(-1)] + '%</small></span><span class="st warn">Practise</span></li><li><span><b>Versus class</b><small class="sub">Above average in ' + above + ' of ' + c.subs.length + ' subjects</small></span><span class="st ' + (above === c.subs.length ? 'ok' : 'warn') + '">' + above + '/' + c.subs.length + '</span></li><li><span><b>Growth since Term 1</b><small class="sub">' + (avgMarks(c) - avgMarks(c, 'Term 1') >= 0 ? '+' : '') + (avgMarks(c) - avgMarks(c, 'Term 1')).toFixed(1) + ' points</small></span><span class="st ok">Rising</span></li></ul></div></div>'
  + '<div class="grid g2"><div class="dc"><h3>Tutor feedback</h3><ul class="lst">' + c.subs.map(s => '<li><span><b>' + s + '</b> · ' + TUTORS[s] + '<small class="sub">' + (FB[s] || 'Steady progress.') + '</small></span>' + '<span class="st ' + (m[s] >= 85 ? 'ok' : 'warn') + '">' + m[s] + '%</span></li>').join('') + '</ul></div><div class="dc"><h3>Reports</h3><ul class="lst">' + T.map(t => '<li><span><b>' + (t === 'Current' ? 'Current term (live)' : t + ' report') + '</b><small class="sub">Grade ' + letter(avgMarks(c, t)) + ' · ' + avgMarks(c, t).toFixed(0) + '%</small></span><span class="row2"><button class="btn sm2" data-act="rdl" data-t="' + t + '" type="button">Download</button><button class="ibs" data-act="rpr" data-t="' + t + '" aria-label="Print ' + t + ' report" title="Print" type="button">' + ic('print') + '</button></span></li>').join('') + '</ul></div></div>'
  + '<div class="tw"><table><thead><tr><th>Subject</th>' + T.map(t => '<th>' + t + '</th>').join('') + '<th>Change</th></tr></thead><tbody>' + c.subs.map(s => { const d = c.terms.Current[s] - c.terms['Term 1'][s]; return '<tr><td>' + s + '</td>' + T.map(t => '<td>' + c.terms[t][s] + '%</td>').join('') + '<td class="' + (d >= 0 ? 'up' : 'dn') + '"><b>' + (d >= 0 ? '▲ ' : '▼ ') + Math.abs(d) + '</b></td></tr>'; }).join('') + '</tbody></table></div>'; },
  mount() { const c = kid(); redraw = () => { const s = [{ name: c.name, data: c.subs.map(x => c.terms[pt][x]), color: col().p }]; if (pt === 'Current') s.push({ name: 'Class average', data: c.subs.map(x => c.avg[x]), color: '#f4b63f' }); barChart($('#c-bar'), c.subs, s); }; redraw(); } };
A.ptm = b => { pt = b.dataset.v; render(true); };

/* ---------- HOMEWORK & TESTS ---------- */
let hwf = 'All';
V.hw = { html() { const c = kid(), all = mine(S.hw), done = all.filter(h => h.done).length, L = all.filter(h => hwf === 'All' || (hwf === 'Done' ? h.done : !h.done)).sort((a, b) => (a.done - b.done) || a.due.localeCompare(b.due)), T = mine(S.tests).filter(t => daysTo(t.date) >= 0).sort((a, b) => a.date.localeCompare(b.date)), R = mine(S.results).slice().sort((a, b) => b.date.localeCompare(a.date));
  return '<h1>Homework &amp; tests</h1><p class="sb">What is due and what is coming up for ' + esc(c.name) + '.</p><div class="grid g2"><div class="dc"><div class="hd2"><h3>Homework</h3><span class="u-fw-700">' + done + ' of ' + all.length + ' done</span></div><div class="bar ok"><i style="width:' + (all.length ? done / all.length * 100 : 0) + '%"></i></div><div class="u-jc-flex-start_mb-6 filters">' + ['All', 'Pending', 'Done'].map(f => '<button class="chip ' + (f === hwf ? 'on' : '') + '" data-act="hwf" data-v="' + f + '" type="button" aria-pressed="' + (f === hwf) + '">' + f + '</button>').join('') + '</div>' + (L.length ? L.map(h => { const od = !h.done && h.due < today(); return '<div class="task ' + (h.done ? 'done' : '') + '"><input type="checkbox" data-act="hwt" data-id="' + h.id + '" ' + (h.done ? 'checked' : '') + ' aria-label="Mark ' + esc(h.title) + ' done"><div class="tt"><b>' + esc(h.title) + '</b><small>' + h.subj + ' · due ' + fmt(h.due) + (h.file ? ' · attached: ' + esc(h.file) : '') + '</small></div>' + (od ? '<span class="st bad">Overdue</span>' : !h.done && daysTo(h.due) <= 1 ? '<span class="st warn">Soon</span>' : '') + '<label class="u-cur-pointer ibs" title="Attach work">' + ic('upload') + '<input type="file" data-hwfile="' + h.id + '" hidden aria-label="Attach file"></label><button class="ibs" data-act="hwd" data-id="' + h.id + '" aria-label="Delete task" type="button">' + ic('trash') + '</button></div>'; }).join('') : empty('check', 'Nothing here. Nice work!'))
  + '<div class="u-mt-14_bt-1-solid-bd_pt-14 f"><div class="f2">' + field('hw-t', 'Add a task', '<input id="hw-t" placeholder="e.g. Revise chapter 5">') + field('hw-s', 'Subject', '<select id="hw-s">' + c.subs.map(s => '<option>' + s + '</option>').join('') + '</select>') + '</div>' + field('hw-d', 'Due date', '<input id="hw-d" type="date" min="' + today() + '" value="' + iso(addDays(2)) + '">') + '<button class="btn" data-act="hwadd" type="button">Add task</button></div></div>'
  + '<div class="dc"><h3>Upcoming tests</h3>' + (T.length ? '<ul class="lst">' + T.map(t => { const n = daysTo(t.date); return '<li><span><b>' + esc(t.name) + '</b><small class="sub">' + t.subj + ' · ' + fmt(t.date) + '</small></span><span class="row2"><span class="st ' + (n <= 4 ? 'warn' : 'ok') + '">' + (n === 0 ? 'Today' : n + ' days') + '</span><button class="ibs" data-act="revise" data-id="' + t.id + '" title="Add a revision task" aria-label="Add revision task" type="button">' + ic('plus') + '</button></span></li>'; }).join('') + '</ul>' : empty('flag', 'No tests scheduled.')) + '</div></div>'
  + '<div class="u-mt-20 tw"><table><thead><tr><th>Test</th><th>Subject</th><th>Date</th><th>Score</th><th>Result</th></tr></thead><tbody>' + (R.length ? R.map(r => { const p = Math.round(r.got / r.of * 100); return '<tr><td>' + esc(r.name) + '</td><td>' + r.subj + '</td><td>' + fmt(r.date) + '</td><td>' + r.got + ' / ' + r.of + '</td><td><span class="st ' + (p >= 80 ? 'ok' : p >= 60 ? 'warn' : 'bad') + '">' + p + '% · ' + letter(p) + '</span></td></tr>'; }).join('') : '<tr><td colspan="5">No results yet.</td></tr>') + '</tbody></table></div>'; },
  mount() { $$('[data-hwfile]').forEach(i => i.onchange = () => { const h = S.hw.find(x => x.id === i.dataset.hwfile); if (i.files[0]) { h.file = i.files[0].name; save(); toast('Attached ' + h.file); render(true); } }); } };
A.hwf = b => { hwf = b.dataset.v; render(true); };
A.hwt = b => { const h = S.hw.find(x => x.id === b.dataset.id); h.done = b.checked; save(); if (h.done) { addXP(10); toast('Great job! +10 XP'); } render(true); };
A.hwd = b => { S.hw = S.hw.filter(x => x.id !== b.dataset.id); save(); render(true); };
A.hwadd = () => { const t = $('#hw-t').value.trim(); if (!bad('hw-t', t ? '' : 'Enter a task name.')) return; S.hw.push({ id: uid(), child: S.kid, title: t, subj: $('#hw-s').value, due: $('#hw-d').value || iso(addDays(2)), done: false, file: '' }); save(); toast('Task added'); render(true); };
A.revise = b => { const t = S.tests.find(x => x.id === b.dataset.id), d = iso(addDays(Math.max(0, daysTo(t.date) - 1))); S.hw.push({ id: uid(), child: S.kid, title: 'Revise for ' + t.name, subj: t.subj, due: d, done: false, file: '' }); save(); toast('Revision task added for ' + fmt(d)); render(true); };

/* ---------- FEES ---------- */
const paysOf = f => f.pays || (f.paid > 0 ? [{ no: f.no || 'BP-0000', amt: f.paid, on: f.paidOn || today(), method: f.method || 'UPI' }] : []);
const feeStatus = f => dueAmt(f) <= 0 ? 'Paid' : f.paid > 0 ? 'Part-paid' : daysTo(f.due) < 0 ? 'Overdue' : 'Due';
const COUPONS = { EARLY10: [.1, 'Early-bird offer'], SIBLING10: [.1, 'Sibling discount'] };
V.fee = { html() { const c = kid(), F = S.fees.filter(f => f.child === S.kid).slice().reverse(), out = F.reduce((a, f) => a + dueAmt(f), 0), paid = F.reduce((a, f) => a + f.paid, 0), fam = S.fees.reduce((a, f) => a + dueAmt(f), 0), nx = F.find(f => dueAmt(f) > 0), all = F.flatMap(f => paysOf(f).map(p => ({ ...p, f }))).sort((a, b) => b.on.localeCompare(a.on));
  return '<h1>Fees &amp; payments</h1><p class="sb">' + esc(c.plan) + ' · ' + c.subs.length + ' subjects · ' + esc(c.name) + '</p><div class="grid g4">' + kpi('rupee', inr(out), 'Outstanding') + kpi('check', inr(paid), 'Paid this term') + kpi('cal', nx ? fmt(nx.due) : 'None', 'Next due date') + kpi('users', inr(fam), 'Family total due') + '</div>'
  + '<div class="u-mt-20 tw"><table><thead><tr><th>Month</th><th>Plan</th><th>Amount</th><th>Discount</th><th>Status</th><th>Action</th></tr></thead><tbody>' + F.map(f => { const s = feeStatus(f), d = dueAmt(f); return '<tr><td>' + f.month + '</td><td>' + esc(f.plan) + '</td><td>' + inr(f.amount) + '</td><td>' + (f.disc ? '−' + Math.round(f.disc * 100) + '%' : '–') + '</td><td><span class="st ' + (s === 'Paid' ? 'ok' : s === 'Overdue' ? 'bad' : 'warn') + '">' + s + (s === 'Due' ? ' ' + fmt(f.due) : '') + '</span></td><td>' + (d > 0 ? '<button class="btn sm2" data-act="pay" data-id="' + f.id + '" type="button">Pay ' + inr(d) + '</button>' : (paysOf(f)[0] ? '<button class="btn sm2 ghost" data-act="rcpt" data-id="' + f.id + '" type="button">Receipt</button>' : '')) + '</td></tr>'; }).join('') + '</tbody></table></div>'
  + '<div class="grid g2"><div class="dc"><h3>Offers &amp; coupons</h3><div class="u-ai-flex-start row2"><div class="u-flex-1_minw-160"><input id="cp" placeholder="Enter code, e.g. EARLY10" aria-label="Coupon code" class="u-tt-uppercase"><span class="err" id="cp-e" role="alert"></span></div><button class="btn" data-act="cpgo" type="button">Apply</button></div><p class="u-c-mu_fs-_85rem_mt-10">Try <b>EARLY10</b> (early-bird) or <b>SIBLING10</b> (second child). Coupons apply to the next unpaid invoice.</p></div>'
  + '<div class="dc"><h3>Auto-pay</h3><div class="tg2"><span><b>Pay automatically on the due date</b><small>Charges your saved UPI mandate. Cancel any time.</small></span><label class="sw"><input type="checkbox" data-act="auto" ' + (S.autopay ? 'checked' : '') + ' aria-label="Auto-pay"><i></i></label></div><div class="tg2"><span><b>Fee reminders</b><small>3 days before the due date</small></span><label class="sw"><input type="checkbox" data-act="pref" data-k="reminders" ' + (S.prefs.reminders ? 'checked' : '') + ' aria-label="Fee reminders"><i></i></label></div></div></div>'
  + '<div class="dc"><div class="hd2"><h3>Payment history</h3><button class="btn sm2 ghost" data-act="feecsv" type="button">Export CSV</button></div>' + (all.length ? '<ul class="lst">' + all.map(p => '<li><span><b>' + inr(p.amt) + '</b> · ' + p.f.month + '<small class="sub">' + fmt(p.on) + ' · ' + p.method + ' · ' + p.no + '</small></span><button class="ibs" data-act="rcpt" data-id="' + p.f.id + '" data-no="' + p.no + '" aria-label="Download receipt" type="button">' + ic('dl') + '</button></li>').join('') + '</ul>' : empty('rupee', 'No payments yet.')) + '</div>'; } };
A.pay = b => payModal(b.dataset.id);
A.auto = b => { S.autopay = b.checked; save(); toast('Auto-pay ' + (b.checked ? 'enabled' : 'disabled')); };
A.pref = b => { S.prefs[b.dataset.k] = b.checked; save(); toast('Preference saved'); };
A.cpgo = () => { const code = $('#cp').value.trim().toUpperCase(), f = S.fees.filter(x => x.child === S.kid && dueAmt(x) > 0 && !x.paid)[0]; let m = '';
  if (!code) m = 'Enter a code.'; else if (!COUPONS[code]) m = 'That code is not valid.'; else if (!f) m = 'No unpaid invoice to apply it to.'; else if (S.coupons.includes(code + S.kid)) m = 'You already used this code.'; else if (code === 'SIBLING10' && S.kid !== 'diya') m = 'Sibling discount applies to the second child. Switch to Diya.';
  if (!bad('cp', m)) return; f.disc = Math.max(f.disc, COUPONS[code][0]); S.coupons.push(code + S.kid); save(); toast(COUPONS[code][1] + ' applied: −' + Math.round(COUPONS[code][0] * 100) + '%'); pushN('fee', 'Coupon applied', code + ' saved ' + inr(f.amount * COUPONS[code][0]) + ' on ' + f.month + '.'); render(true); };
