A.msend = () => { const i = $('#mi'), t = i.value.trim(); if (!t) return; const key = mt; S.msgs[key].push({ me: 1, text: t, t: Date.now() }); save(); i.value = ''; const m = $('#msgs'); if (m.querySelector('.empty')) m.innerHTML = ''; m.insertAdjacentHTML('beforeend', bub(S.msgs[key].at(-1)) + '<div class="bub" id="typ"><span class="typing"><i></i><i></i><i></i></span></div>'); m.scrollTop = m.scrollHeight;
  setTimeout(() => { const r = { me: 0, text: botReply(t, key), t: Date.now() }; S.msgs[key].push(r); if (cur === 'msg' && mt === key) { $('#typ') && $('#typ').remove(); $('#msgs').insertAdjacentHTML('beforeend', bub(r)); $('#msgs').scrollTop = $('#msgs').scrollHeight; } else { S.unread[key]++; pushN('msg', 'New message', CONTACTS.find(c => c[0] === key)[1] + ' replied.'); } save(); badges(); }, 1400); };

