A.kgo = () => { const n = $('#ak-n').value.trim(); if (!bad('ak-n', n ? '' : 'Enter a name.')) return; const g = +$('#ak-g').value, subs = g <= 5 ? ['Mathematics', 'English', 'Science'] : ['Mathematics', 'Science', 'English', 'Computer Science'], r = rng(g * 13 + n.length), id = uid(), marks = {}, avg = {}; subs.forEach(s => { marks[s] = 70 + Math.round(r() * 20); avg[s] = 68 + Math.round(r() * 8); }); seed(); const k = seed.mk(id, n, g, subs, marks, avg, 0); k.board = $('#ak-b').value; k.plan = g > 5 ? 'Standard plan' : 'Basic plan'; k.fee = g > 5 ? 3200 : 1800; S.kids[id] = k; const t = new Date();
  [2, 1, 0].forEach(m => { const x = new Date(t.getFullYear(), t.getMonth() - m, 10); S.fees.push({ id: uid(), child: id, month: MON[x.getMonth()] + ' ' + x.getFullYear(), due: iso(x), amount: k.fee, plan: k.plan, disc: 0, paid: m ? k.fee : 0, paidOn: m ? iso(x) : null, method: m ? 'UPI' : null, no: m ? 'BP-' + (6000 + Math.floor(Math.random() * 900)) : null }); }); S.kid = id; save(); closeMod(); kids(); xpcard(); render(true); toast(n + ' added'); };
