const hook = (k, f) => { const m = V[k].mount; V[k].mount = () => { m && m(); f(); }; };
const hash = s => [...String(s)].reduce((a, ch) => (a * 31 + ch.charCodeAt(0)) >>> 0, 7);
const initials = n => String(n || '?').trim().split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase();
const nextInv = () => S.fees.filter(f => f.child === S.kid && f.paid === 0 && dueAmt(f) > 0).sort((a, b) => a.due.localeCompare(b.due))[0];
