function avatar() { const a = $('#avt'), p = S.profile; if (!a) return; if (p.photo) { a.style.backgroundImage = 'url(' + p.photo + ')'; a.textContent = ''; a.classList.add('ph'); } else { a.style.backgroundImage = ''; a.classList.remove('ph'); a.textContent = initials(p.name); } a.title = p.name; a.setAttribute('aria-label', 'Account menu for ' + p.name); }
