const FAQS = [['Fees', 'When are fees due?', 'Fees are due by the 10th of every month. We send a reminder 3 days before.'], ['Fees', 'Can I pay in two parts?', 'Yes. Choose “Pay in two parts” at checkout. The balance stays on the invoice.'], ['Fees', 'How do I get a receipt?', 'Open Fees & payments and tap the download icon beside any payment.'], ['Classes', 'How do I reschedule a class?', 'Go to Book sessions, pick the session and choose Reschedule. Tutors confirm within a few hours.'], ['Classes', 'What if my child misses a class?', 'Apply for leave under Attendance. Tell us 3 hours before and we arrange a make-up session.'], ['Learning', 'How quickly are doubts answered?', 'Doubts posted before 9 PM are answered by the next morning. Weekend doubt sessions are free.'], ['Account', 'How do I add another child?', 'Open Profile & settings, then Your children, then Add child. The sibling discount applies to the second child.'], ['Account', 'Where is my data stored?', 'In this demo, everything is stored in your browser. You can export or reset it from Profile & settings.']];
