const syncTk = () => { let ch = false; (S.tickets = S.tickets || []).forEach(t => { if (t.closed || t.status === 'Resolved') return; const el = Date.now() - t.t; if (el > 14000) { t.status = 'Resolved'; t.replies = (t.replies || []).concat({ who: 'BrightPath support', text: TKR[t.cat] || TKR.Other, t: Date.now() }); pushN('msg', 'Ticket resolved', t.no + ' · ' + t.subj + ' has been resolved.'); ch = true; } else if (el > 5000 && t.status === 'Open') { t.status = 'In progress'; ch = true; } }); if (ch) save(); return ch; };
