  $('#pf').onchange = e => { const f = e.target.files[0]; if (!f) return; if (!/^image\//.test(f.type)) return toast('Please choose an image file.'); const r = new FileReader(); r.onload = () => { const im = new Image(); im.onload = () => { const s = 160, cv = document.createElement('canvas'); cv.width = cv.height = s; const x = cv.getContext('2d'), m = Math.min(im.width, im.height); x.drawImage(im, (im.width - m) / 2, (im.height - m) / 2, m, m, 0, 0, s, s); S.profile.photo = cv.toDataURL('image/jpeg', .85); save(); avatar(); render(true); toast('Profile photo updated'); }; im.onerror = () => toast('That image could not be read.'); im.src = r.result; }; r.readAsDataURL(f); };
