/* ---------- COMMAND PALETTE ---------- */
const CMDS = () => [...NAV.filter(n => n.length > 1).map(n => ({ t: 'Go to ' + n[1], i: n[2], k: 'go', run: () => go(n[0]) })), { t: 'Pay outstanding fee', i: 'rupee', k: 'action', run: A.payfirst }, { t: 'Book a session', i: 'plus', k: 'action', run: () => go('book') }, { t: 'Download latest report', i: 'dl', k: 'action', run: A.repdl }, { t: 'Start a focus session', i: 'clock', k: 'action', run: () => { go('tools'); setTimeout(() => !T.run && A.tgo(), 50); } }, { t: 'Export calendar (.ics)', i: 'cal', k: 'action', run: A.ics }, { t: 'Message the front desk', i: 'msg', k: 'action', run: () => { mt = 'Desk'; go('msg'); } }, { t: 'Mark all notifications read', i: 'check', k: 'action', run: () => { A.nall(); } }, { t: 'Raise a support ticket', i: 'help', k: 'action', run: () => go('supp') }, { t: 'Log out', i: 'x', k: 'action', run: logout }, { t: 'Toggle dark mode', i: 'moon', k: 'action', run: () => $('[data-theme-toggle]').click() }];
function palette() { let q = '', sel = 0, L = CMDS(); const m = modal('<input id="cq" placeholder="Type a command or page name…" aria-label="Search commands" autocomplete="off"><ul id="cl" role="listbox"></ul>', 'cmd'), draw = () => { L = CMDS().filter(c => c.t.toLowerCase().includes(q.toLowerCase())); sel = Math.min(sel, Math.max(0, L.length - 1)); $('#cl', m).innerHTML = L.length ? L.map((c, i) => '<li role="option" class="' + (i === sel ? 'on' : '') + '" data-i="' + i + '">' + ic(c.i) + c.t + '<small>' + c.k + '</small></li>').join('') : '<li>No matches</li>'; };
  draw(); const run = i => { const c = L[i]; if (c) { closeMod(); setTimeout(c.run, 30); } }; $('#cq', m).oninput = e => { q = e.target.value; sel = 0; draw(); }; $('#cq', m).onkeydown = e => { if (e.key === 'ArrowDown') { sel = (sel + 1) % L.length; draw(); e.preventDefault(); } else if (e.key === 'ArrowUp') { sel = (sel - 1 + L.length) % L.length; draw(); e.preventDefault(); } else if (e.key === 'Enter') run(sel); }; $('#cl', m).onclick = e => { const li = e.target.closest('li[data-i]'); if (li) run(+li.dataset.i); }; }
$('#srch').onclick = palette;
document.addEventListener('keydown', e => { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); closeM ? closeMod() : palette(); } else if (e.key === '/' && !/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName) && !closeM) { e.preventDefault(); palette(); } });

